const FEEDCHK = {};
function feedAsOf(f) {
  if (f[4] === "rl") return RL().nov.asOf;
  if (f[4] === "live") return "";
  if (f[4] === "pack") { const b = Object.values(DATA.d).map((K) => K && K.built).filter(Boolean).sort(); return b.length ? b[0] + (b[0] !== b[b.length - 1] ? " to " + b[b.length - 1] : "") : ""; }
  return f[4];
}
function feedsRender() {
  const el = $("feeds"); if (!el) return;
  el.innerHTML = `<div class="tw"><table class="t"><thead><tr><th>Dataset</th><th>Used for</th><th>This file has data from</th><th>Publisher last updated it</th><th>How to update</th></tr></thead><tbody>${FEEDS.map((f) => {
    const c = FEEDCHK[f[1]], mine = feedAsOf(f), newer = c && c.d && mine && c.d > mine.slice(-10);
    return `<tr><td><a href="https://${f[0]}/d/${f[1]}">${esc(f[2])}</a> <code>${f[1]}</code></td><td>${esc(f[3])}</td><td>${esc(mine.split(" to ").map(dmy).join(" to ") || "–")}</td><td>${c ? (c.d ? dmy(c.d) + (newer ? ' <span class="nchip mid">newer data</span>' : "") : esc(c.e)) : "–"}</td><td class="small">${esc(f[5])}</td></tr>`;
  }).join("")}</tbody></table></div>`;
}
async function feedsCheck() {
  $("feedsRun").disabled = true;
  await Promise.all(FEEDS.map(async (f) => {
    try { const r = await fetch(`https://${f[0]}/api/views/${f[1]}.json`); const j = await r.json(); FEEDCHK[f[1]] = { d: new Date(j.rowsUpdatedAt * 1000).toISOString().slice(0, 10) }; }
    catch (e) { FEEDCHK[f[1]] = { e: "could not check (offline?)" }; }
  }));
  $("feedsRun").disabled = false;
  feedsRender();
}

/* ---- readable column names: "tier45_blocks" reads "tier 4–5 blocks" ---- */
const colLabel = (c) => String(c).replace(/tier45/g, "tier 4–5").replace(/tier3plus/g, "tier 3+").replace(/_/g, " ");

/* ---- every results table sorts: click a heading; the chip shows the order (A→Z / Z→A, 1→9 / 9→1) ---- */
const cellNum = (s) => { const v = s.replace(/[,$%\s]/g, "").replace(/(min|km|m)$/, ""); return /^-?\d*\.?\d+$/.test(v) ? parseFloat(v) : null; };
document.addEventListener("click", (e) => {
  const th = e.target.closest("table.mlist:not(.ltab) thead th");
  if (!th || e.target.closest("a,button,input,select")) return;
  const tb = th.closest("table"), body = tb.tBodies[0];
  if (!body || body.rows.length < 2) return;
  const i = [...th.parentNode.children].indexOf(th), dir = th.getAttribute("aria-sort") === "ascending" ? -1 : 1;
  const rows = [...body.rows], txt = (r) => (r.cells[i] ? r.cells[i].textContent.trim() : "");
  const num = rows.every((r) => { const t = txt(r); return !t || t === "–" || cellNum(t) != null; });
  rows.sort((a, b) => {
    if (num) { const x = cellNum(txt(a)), y = cellNum(txt(b)); return ((x == null ? -Infinity : x) - (y == null ? -Infinity : y)) * dir; }
    return txt(a).localeCompare(txt(b), undefined, { numeric: true, sensitivity: "base" }) * dir;
  });
  tb.querySelectorAll("thead th").forEach((h) => { h.removeAttribute("aria-sort"); delete h.dataset.so; });
  th.setAttribute("aria-sort", dir > 0 ? "ascending" : "descending");
  th.dataset.so = num ? (dir > 0 ? "1→9" : "9→1") : dir > 0 ? "A→Z" : "Z→A";
  rows.forEach((r) => body.appendChild(r));
});

/* ---- Display settings: light / dark / follow the device, and header animation ---- */
function dispApply() {
  let t = "auto", m = "1";
  try { t = localStorage.getItem("flushing-theme") || "auto"; m = localStorage.getItem("flushing-motion") || "1"; } catch (e) {}
  if (t === "auto") document.documentElement.removeAttribute("data-theme"); else document.documentElement.setAttribute("data-theme", t);
  document.documentElement.classList.toggle("still", m === "0");
  document.querySelectorAll('input[name="theme"]').forEach((r) => (r.checked = r.value === t));
  if ($("motion")) $("motion").checked = m !== "0";
}
function dispWire() {
  document.querySelectorAll('input[name="theme"]').forEach((r) => (r.onchange = () => { try { localStorage.setItem("flushing-theme", r.value); } catch (e) {} dispApply(); if (D) render(); }));
  if ($("motion")) $("motion").onchange = () => { try { localStorage.setItem("flushing-motion", $("motion").checked ? "1" : "0"); } catch (e) {} dispApply(); };
  // menus in the top bar: one open at a time; Esc or a click elsewhere closes them
  const menus = () => [...document.querySelectorAll(".top details.more")];
  menus().forEach((d) => d.addEventListener("toggle", () => { if (d.open) menus().forEach((o) => o !== d && (o.open = false)); }));
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") menus().forEach((d) => { if (d.open) { d.open = false; d.querySelector("summary").focus(); } }); });
  document.addEventListener("click", (e) => { if ($("disp") && !$("disp").contains(e.target)) $("disp").open = false; });
  dispApply();
}

/* ---- stage 2: City-comparable coverage (LL58 report, Table 4, p. 8) ----
   The City counts every restroom on its list whatever its season or hours, run by Parks, DOT, libraries, POPS and some
   MTA transit, and walks a street network (Parks' Vital Parks Explorer). Here: every row of the City list counts
   (Future rows excepted); closed rows in or out; Port Authority and Hudson River Park in or out; walk = straight line ×
   detour ÷ speed, with the map's open-water rule. cityDist() gives each block's residents and straight-line distance. */
function cityDist(o) {
  const out = [];
  DATA.order.forEach((id) => {
    const K = prep(DATA.d[id]);
    const R = K.rest.filter((r) => r.li != null && r.op4 !== "Future" && (o.closed || r.st === "Operational") && (o.pa || !/^(Port Authority|Hudson River Park)$/.test(r.op)));
    K.blocks.forEach((b) => {
      if (!b.pop) return;
      let best = Infinity;
      R.forEach((r) => { const d = Math.hypot(r.x - b.c[0], r.y - b.c[1]); if (d < best && !cross(K, b, r, { water: false })) best = d; });
      out.push([b.pop, best, id]);
    });
  });
  return out;
}
const coverShares = (B, det, speed, Ts) => { const pop = B.reduce((a, x) => a + x[0], 0); return Ts.map((T) => B.reduce((a, x) => a + ((x[1] * det) / speed <= T ? x[0] : 0), 0) / pop); };
// Residents beyond a walk on the map's own rule (scoreAll), for a district and settings o, p.
function beyondOf(K, o, p, T) { const res = noEdits(K, () => scoreAll(K, o, [], { ...p, T })); let n = 0; K.blocks.forEach((b, i) => { if (!(res[i].walk <= T)) n += b.pop; }); return n; }

